<?php
namespace App\Actions\ServiceOrders;use App\Enums\PaymentStatus;use App\Models\ServiceOrder;
class RecalculateServiceOrderTotals{public function execute(ServiceOrder $o):ServiceOrder{$subtotal=(float)$o->items()->selectRaw('COALESCE(SUM(quantity * unit_price),0) total')->value('total');$itemDiscount=(float)$o->items()->sum('discount_amount');$total=max(0,$subtotal-$itemDiscount-(float)$o->discount_amount+(float)$o->shipping_fee);$paid=(float)$o->paid_amount;$paymentStatus=(string)$o->payment_status;if($paymentStatus!==PaymentStatus::REFUNDED){$paymentStatus=$paid<=0?PaymentStatus::UNPAID:($total>0&&$paid<$total?PaymentStatus::PARTIAL:PaymentStatus::PAID);}$o->update(['subtotal'=>$subtotal,'total_amount'=>$total,'payment_status'=>$paymentStatus]);return $o->refresh();}}
